-- Beach casebook -> FIVB Illustrated Beach Volleyball Casebook 2025.
--
-- Source: https://volley.ee/wp-content/uploads/2020/06/ILLUSTRATED-BVB-CASEBOOK-2025.pdf
-- (marked OFFICIAL, based on the 2025-2028 rules; fivb.com still links the 2023 edition).
-- The stored cases predate even the 2023 edition. Cases were matched by content, not number:
--
-- 1. Teams are "A" and "B" since 2023, no longer "L" and "R" (22 cases).
-- 2. 5.1.6 -> 5.1.7, 5.1.7 -> 5.1.8, 6.3.10 -> 6.3.11, 6.3.11 -> 6.3.12, with their rule links.
-- 3. 5.1.5 gets the current ruling (correct the line, then call in/out) and 5.1.6 is added
--    (line only slightly moved: call it "in"). Both replace the old single 5.1.5.
-- 4. 6.3.10 is added (tree branch over the service zone).
-- 5. 9.20 (tree branch hit during the rally) is removed: it is in neither the 2023 nor the 2025 edition.
--
-- Rule references and the 15 video links already match 2025.
--
-- Apply: npx wrangler d1 execute readvolley-db --remote --file=scripts/beach-casebook-2025.sql

-- 1. Team letters
UPDATE casebook SET case_text = 'In a match the ball is played legally by both teams above the net in a joust (extended contact with the ball by opponents), and then lands outside the court of Team “A”. Who now has the serve?', case_ruling = 'The team “A” will serve, because after the joust and the ball goes out, the last contact was made by the team on the opposite side from where the ball touched the ground.' WHERE id = '5_2_1_beach';
UPDATE casebook SET case_text = 'When the ball was completely above the court of team A, it was attacked by the team A player. Simultaneous with this, the opponent blocker also contacted the ball. Is this a blocking fault?', case_ruling = 'This is not a fault of either player. It would be a fault if the blocker had contacted the ball first, however. It is important to appreciate that this ruling only applies to attack-block simultaneous actions.
Had the team A player been setting the ball, on the other hand, because the ball was completely in the space of team A, the blocker would have been at fault for “reaching beyond the net” to intercept an internal pass.' WHERE id = '5_4_2_beach';
UPDATE casebook SET case_text = 'If a ball is passed by player A outside the antenna on the side of the 2nd Referee and his/her teammate, coming under the net to try to retrieve the ball, is deliberately obstructed by the player on the opponent side, should the 2nd Referee whistle this action as interference?', case_ruling = 'Yes. This is a form of interference even if a physical contact has not occurred. It is illegal for a player, to substantially alter his/ her position in order to prevent the opponents from making a legitimate play on the ball.
The other way around, despite at Beach Volleyball a player being allowed to run through the opponent''s court to retrieve balls at the opponent''s free zone regardless his/her full awareness on how the ball travelled the crossing space, that player, in the case the ball travelled inside the crossing space will be accountable for possible interference with the opponents’ ability to play the ball, i.e.: the case where the opponent player would be inhibited from even making a decision whether or not to play the ball...so preventing proper decision making.
This might be a valid basis for calling it interference.' WHERE id = '5_5_4_beach';
UPDATE casebook SET case_text = 'After a block, the blocker (Team B) falls on the sand, partially on the opponent side (Team A). The ball, hitting the net and entering the space of Team A after the block, falls on the blocker, still lying on the side of the opponent. The attacking team had no chance of playing this ball. Is this called interference?', case_ruling = 'Interference would only occur if the blocking player lying in the ground would hinder an opponent’s legitimate attempt to play the ball. As this was not the case here, the referee should treat this ball as if it had landed on the ground, with the blocking team consequently and correctly winning the rally.' WHERE id = '5_5_5_beach';
UPDATE casebook SET case_text = 'When a ball was played between the antennae going to the opponent’s (Team B’s) free zone and a player, trying to go to this ball to play it, was obstructed by the opponent, should the 1st Referee see this as interference?', case_ruling = 'No, the overriding consideration must be that the team (Team A) directing the ball towards the opponent’s side does not have a legal play on the ball because the ball passed completely between the antennae and so only the Team B players may play the ball. Should the Team A player actually contact the ball in this case, the 1st Referee must immediately whistle a fault.' WHERE id = '5_5_6_beach';
UPDATE casebook SET case_text = 'A ball was blocked straight down. Before the ball landed on the opponent’s court, the ball touched the leg of the middle blocker, who was already standing on the sand without the intention of kicking the ball. If there was no leg hit, the ball would have landed clearly on the sand on team B’s side.
Can the middle blocker’s leg touch be considered as an interference to the opponent’s play?', case_ruling = 'No. Because the middle blocker’s leg touch was unintentional and he already stood on the sand, he made no mistake.
However, if the contact was well above the sand, and there was an opponent player with a potential play on the ball, then this is interference.' WHERE id = '5_5_10_beach';
UPDATE casebook SET case_text = 'After a dig by team A the ball went high around the antenna and it was supposed to land close to the sideline. It was difficult to determine if the path was within the crossing space or over the antenna. A player from team A was running under the net to replay the ball. Meanwhile a player from team B was also ready to play close to the sideline. However, the 2 players almost collided with each other, the player of team B played the ball successfully and the rally continued. How should it be determined if a fault has been committed and in this case which player was at fault?', case_ruling = 'The crucial point is the trajectory of the ball.
If the ball clearly passed the net plane within the antennae, i.e., through the crossing space, team A had no right to play it back. It means the running player of team A interfered with the opponent’s play and made a fault regardless, if the opponent successfully hit the ball.
If the ball clearly passed the net plane over or outside the antennae, i.e., partly or totally outside of the crossing space, team A had the right to play it back. In this case the team B’s player interfered with the opponent’s play and made a fault regardless of whether the opponent successfully hit the ball.
If the ball’s trajectory was in doubt, and neither referees, nor line judges could determine this, both players may legally think, that their action to try to play the ball is legal. It is impossible to determine the faulty player. In such a situation it is worth not stopping the rally.' WHERE id = '5_5_11_beach';
UPDATE casebook SET case_text = 'After the whistle for service, the captain of team A requests a TO from the 2nd Referee and starts walking to the chairs. The 2nd Referee does not blow the whistle and tries to get the team back into the playing court. The 1st Referee, seeing this, calls a replay, and grants team A their request for TO. Is this the proper procedure?', case_ruling = 'No - after the referee has whistled for service, the captain of team A had no right to ask for the TO, and certainly was not granted permission to leave the court.
After the whistle for service by the 1st Referee, the service should be executed.' WHERE id = '5_6_11_beach';
UPDATE casebook SET case_text = 'If the ball is set cleanly, and the wind catches the ball and places the ball at the opponent side of the net, should the 1st Referee penalize the team for an attack hit fault?', case_ruling = 'No. This is a common misinterpretation of the rules and is not a fault. If the intention of the team “A” player is to set the ball to their partner, no fault exists. The wind causing the ball to cross over the net or the trajectory of the ball not being in line with the player’s shoulders is irrelevant in deciding on this fault.' WHERE id = '5_7_4_beach';
UPDATE casebook SET case_text = 'During a match, the captain of team A requested a second TO in the set. The 2nd Referee accepted it, while stating to the scorer that the first TO was to team B. After correction of the score sheet by the scorer, later in the set, team B requested (their first) TO. After rejection by the 2nd Referee, and the protest of team B, the 2nd Referee realized that team A had been granted two TO’s in the set. What would be the solution at the time of the match?', case_ruling = 'Although the right moment of the second request of the captain of team A could be tracked, after playing the next rally, this can only be considered as a fault of the referee concerned.
Team B has no right to go back in time and replay the match from the point that team A received their second TO. (At the time this should have been recorded as an improper request or as a delay sanction.)' WHERE id = '6_1_4_beach';
UPDATE casebook SET case_text = 'During a match, while directly walking into his team’s area, the team A player who was not the captain requested a TO. The 2nd Referee did not accept the request and an “improper request” was issued to team A. In the meantime, the team A captain requested a TO at the same interruption, which was also not accepted by the 2nd Referee. Was the 2nd Referee correct?', case_ruling = 'The referee is correct in issuing an “improper request”. This is to be rejected without sanction unless repeated, or it affects or delays the game. However, depending on the circumstances, the described scenario could lead to one of the two following consequences:
1) In case no delay sanction applies, there is no rule that says there cannot be a legitimate request from the captain during the same interruption. So, in such circumstance the 2nd Referee should have accepted the TO request from the captain.
2) If there was a delay sanction applied, then the captain’s TO request would not be permitted in the same interruption.' WHERE id = '6_1_6_beach';
UPDATE casebook SET case_text = 'During a match, the captain of team A requests a second TO in the set. The 2nd Referee authorises it. As the players walk to their chairs, the scorer informs the 2nd Referee that team A already had one TO in that set. The 2nd Referee calls both teams back to their playing positions, and the 1st Referee gives a delay sanction to team A.
Was this the right procedure?', case_ruling = 'This is, considering the elapsed time, the right solution.
The 2nd Referee must always be aware of the number of TOs used, and he should have rejected the request and instructed the scorer to register an improper request on the score sheet.' WHERE id = '6_2_6_beach';
UPDATE casebook SET case_text = 'At 22:22 in the 1st set and following an attack by Team B, Team A’s defending player miss-directs the ball towards the back of his own court (close to the end line). Team A’s partner starts chasing the ball but before reaching it, a stray ball enters the free zone between the panels and the same end line, in sight of all players and referees.
Both Team B players react verbally and wave their arms towards the referees re: the external ball entering the playing area, and consequently hesitate to continue the rally, delaying their movements, and losing focus, which allowed Team A to easily ground the ball on Team B’s court and win the rally. Conversely, the Team A players throughout did not question the position of the stray ball, maintained focus, and did not stop playing. Although both referees saw the external ball entering the playing area during the rally, and the gestures and hesitation by Team B players, the 1st referee awarded the point to Team A, advancing the score to 23:22. (Unfortunately the score was not advanced by the scorer and remained at 22:22 on the e-Scoresheet).
The ensuing actions resulted in a 14-minute delay to the match before play resumed.
Should the referees have stopped the rally and replayed, and does either team have a case for protest?', case_ruling = 'Rule 17.2 states that “If there is any external interference during the game, the play has to be stopped and the rally is replayed.” In this case both referees saw the external ball invading the playing area, and should have been able to recognise the claim by Team B players and their hesitation, yet both referees considered that the action did not interfere with play.
The incident described suggests external interference, so a straightforward application of the rule would have been: interrupt play and replay the rally.
This would have entitled Team B to a legitimate request for a protest protocol due to suspected misinterpretation of the rule.
If the protest is based on this as a judgment call rather than a misinterpretation/misapplication of the rule, the TD under the advice of the RC could not uphold the protest protocol. This would have serious financial consequences for Team B ($500). “Clever refereeing” implies common sense. If there is no reaction including when players do not care about it and want to keep playing, then "clever refereeing" should prevail.
Finally, a 14-minute delay related to a dispute of a refereeing decision is totally unacceptable in our sport.' WHERE id = '6_3_10_beach';
UPDATE casebook SET case_text = 'During a main draw Women’s match, the organising committee decided to stop all matches due to a thunderstorm. The interruption lasted for approximately 1 hour.
The score recorded on the e-Score sheet at the time of the interruption in the 2nd set was 8-6 in favour of Team A, with Team A serving.
At the end of the warm up to resume the match, with the 1st referee on the stand, Team B insisted first with the 2nd referee and the scorer that the score was incorrect and then from the court they addressed the TD/RC in the spectator’s area, saying that they were leading 8-6, and not Team A. The complaint was not an official protest.
The RC decided to go and ask the 2nd referee to check the scoresheet and after a few seconds, the 2nd referee advised that the score was correct (8-6 to Team A), and that he was sure of it. The RC then told Team B that they had to resume play, which is what they did.
Later the RC decided to download the video footage of the match and the scoresheet. He realised that when the score was 7-6 in favour of Team A, when Team A had actually served into the net. The score should have become 7-7 at the time of the interruption with Team B serving.
By checking the scoresheet, the RC found that the scorer had awarded a point to Team A by mistake (making it 8-6 for Team A). Nobody on the court at that moment had realised the mistake, and everybody left due to the thunderstorm interruption.', case_ruling = 'The scorer clearly made an error at the e-scoring when Team B won the rally and the service, after a missed serve by Team A at 7-6, with the teams switching courts as required (the court switch should have been recorded at 7-7).
A number of other procedural errors occurred, which would have prevented the embarrassing situation with an incorrect score and incorrect team to serve when play resumed. This included:
1) immediately following the court switch, the 2nd and the 1st referee, before/or eventually after they left the court, did not properly check (as required) that all was correctly registered at the e-scoresheet (with the correct score, the correct server, etc.)
2) when Team B questioned the score, after already such a long stop due to weather conditions, the RC should have taken the opportunity for only an extra couple of minutes to go and look at the official video footage for the correct score and server.' WHERE id = '6_3_11_beach';
UPDATE casebook SET case_text = 'At 20-20 1st set, after team A scoring the 21st point, one of the team B players complaints from the fact that the referee did not call what in his opinion was a bad setting action.
Whilst team B had already received a misconduct formal warning (yellow card) in the course of that set, and the first referee considered the action of the team B player as a repetition of minor misconduct issuing team B player a misconduct penalty, this resulted in the score 22-20 for team A. Was the first referee, correct?', case_ruling = 'Additional action of minor misconduct by any player in a team previously sanctioned with a misconduct formal warning (yellow card) during the match will result in a misconduct penalty, and so, depending on the seriousness of the minor misconduct, the referee has the authority to sanction the player with a misconduct penalty.
However, the referee must carefully evaluate the level of seriousness of such minor misconduct, as to prevent deciding the set (or the game) with a penalty sanction.' WHERE id = '7_1_3_beach';
UPDATE casebook SET case_text = 'During a Quarter Final match on Centre Court, with the score at 1:0 to Team A in set 3, Team A won the next rally. The scorer added one point for Team A on the e-score tablet. However, due to the tablet’s slow response, it did not initially show the point for Team A and after a few seconds, the Scorer, believing that the point had not been added, hit the button again to add the point for Team A. After a few seconds the tablet now displayed the score of 3:0 to Team A.
Despite advice from colleagues, the scorer insisted that 3:0 had to be the correct score. Team A finally won the third set 15:12.
Sometime after the score sheet was signed, the error was confirmed.
How should the scoring error have been prevented? What can now be done regarding the match result?', case_ruling = 'Tight schedules in Beach events mean that it is vital that all scoring issues and protests are dealt with at the time. Since the score sheet was signed by both captains, without protest, ratifying the result, nothing can now be done regarding this mistake. There were a minimum of FIVE (5) officials who should have identified the scoring error, and who should have used their influence to correct it before the next rally commenced:
1) the Scorer should have been extra vigilant to know the score before advancing it (i.e., 1:0), and what it should be after adding a point (in this case 2:0).
2) the Assistant Scorer (who was running a manual backup paper score sheet, who did advise on the correct score) should have been more insistent, and should have suggested calling over the 2nd Referee to discuss the problem before resuming the match.
3) the Reserve Referee who was running the backup e-Score/Tablet, should have made the RC aware during the first set that there were problems with the technology and that they were unable to keep score securely during the match.
4) both Referees should be checking the score after every rally, to ensure it advances only by one point each rally, and that the score is correct on the litescore display and large scoreboards.
Greater teamwork, while respecting individual responsibilities, and unhesitatingly speaking up, would ensure this type of error would not happen. The Challenge Referee and the Official Timing/Scoreboard Operator who were part of this match, could also have played a role in addressing the scoring error; however, the five officials listed above had the primary responsibility to ensure the score was correct before the start of the fourth rally. Even in a case where there are not as many officials assigned to a match (i.e.: side court matches), the 1st & 2nd Referee must be checking the score after every rally to minimise the chance of this kind of scoring error.' WHERE id = '8_1_2_beach';
UPDATE casebook SET case_text = 'During a match, one of the players of team A raced quickly after the ball and made a sensational dig as he fell over the sponsorship. The player’s extraordinary effort drew great applause from the crowd. However, the player’s contact was slightly extended and the 1st Referee blew his whistle and signaled the ball as a “Catch”?', case_ruling = 'The referees should remember that they are not only the person who administers the match under the rules, but they allow under their guidance the promotion of the sport of Beach Volleyball.
Developing the spectacular element is an important aspect of any sport’s promotion.
The referee must keep a balance between applying rigidly the technical requirements of the sport with the promotional, cultural and societal aspects of a sport.
It is necessary for the referee to allow this spectacular action of the game to be emphasized at the expense of its technical nature.' WHERE id = '9_3_beach';
UPDATE casebook SET case_text = 'If a player disagrees with the scorer and the referees about who is to serve, what should the referees check?', case_ruling = 'There are 4 boxes labeled I to IV (1-4) which correspond to the service order. The number of the player is inserted next to this box. The team that serves first will be serving # I and # III in the serving order. The other team # II and # IV. The scorer follows a regular pattern in recording the services, regardless of which team commences the service, A (left side) or B (right side).
It is important that the 2nd Referee checks that the very first service of the match is recorded next to the top box # I. This will ensure that the service order is correctly initially recorded.' WHERE id = '9_4_beach';
UPDATE casebook SET case_text = 'The teams finish their official warm up and enter the court to start their match. Player #1 for team “A” goes to the serving position. The scorer immediately draws the referee’s attention to the fact that the score sheet states that the first server should be #2. What should the scorer now do?', case_ruling = 'The scorer should wait until the referees have finished determining if there is the possibility of an error in the communication of the service order. If the 1st Referee authorises the #1 player of team A to serve, the scorer should just change team A’s service order box.
However, if the #2 player is made to serve, no change to the score sheet is necessary.
The scorer is correct in informing the officials and players of this problem but they cannot insist the players change server. This is the responsibility of the referees.' WHERE id = '10_5_beach';
UPDATE casebook SET case_text = 'After winning the coin toss the captain of Team B returns to the court to determine the side. After signing the score sheet, he didn’t inform the scorer about his/her choice. What should the scorer do to ensure that this information is received?', case_ruling = 'The scorer should be active in obtaining the decision for court and service order from team B.
If neither the referees nor team have conveyed the decision to the scorer after 1 minute, the referees (usually 2nd Referee) should be informed of this.' WHERE id = '10_6_beach';
UPDATE casebook SET case_text = 'The captain of team “A”, at the end of the “B” team’s timeout, requests a timeout. What procedure should the scorers follow now?', case_ruling = 'The scorer should initially verify which team called the time out and then record it in the appropriate box. While the teams are at their designated chairs the scorer should indicate to the 2nd Referee the team’s respective number of time outs used (both one). In this case no more timeouts are allowed. This would then be communicated by the 2nd Referee, not the scorer, to the 1st Referee and to the teams at the end of the timeout.' WHERE id = '10_7_beach';
UPDATE casebook SET case_text = 'If a player disagrees with the scorer and the referees about who is to serve, what should the scorer check?', case_ruling = 'The score sheet is designed to allow the service order to be checked easily.
There are 4 boxes labeled I to IV (1-4) which corresponds to the service order. The number of the player is inserted next to this box. The team that serves first will be serving #I and #III in the serving order. The other team #II and #IV. The scorer follows a regular pattern in recording the services, regardless of which team commences the service, A (left side) or B (right side).
It is important that the 2nd Referee checks that the very first service of the match is recorded next to the top box # I. This will ensure that the service order is correctly recorded in the first instance.' WHERE id = '10_24_beach';

-- 2. Renumber, highest first so no id is taken twice
INSERT INTO casebook (id, case_number, case_text, case_ruling, video_link, case_section, case_subsection, chapter_n, chapter_name, document_type, rule_ref_text, rule_reference_array, rules_type, chapter_id) SELECT '5_1_8_beach', '5.1.8', case_text, case_ruling, video_link, case_section, case_subsection, chapter_n, chapter_name, document_type, rule_ref_text, rule_reference_array, rules_type, chapter_id FROM casebook WHERE id = '5_1_7_beach';
UPDATE casebook_rules SET casebook_id = '5_1_8_beach' WHERE casebook_id = '5_1_7_beach';
DELETE FROM casebook WHERE id = '5_1_7_beach';
INSERT INTO casebook (id, case_number, case_text, case_ruling, video_link, case_section, case_subsection, chapter_n, chapter_name, document_type, rule_ref_text, rule_reference_array, rules_type, chapter_id) SELECT '5_1_7_beach', '5.1.7', case_text, case_ruling, video_link, case_section, case_subsection, chapter_n, chapter_name, document_type, rule_ref_text, rule_reference_array, rules_type, chapter_id FROM casebook WHERE id = '5_1_6_beach';
