INSERT INTO casebook (id, case_number, case_text, case_ruling, video_link, case_section, case_subsection, chapter_n, chapter_name, document_type, rule_ref_text, rule_reference_array, rules_type, chapter_id) SELECT '6_3_11_beach', '6.3.11', case_text, case_ruling, video_link, case_section, case_subsection, chapter_n, chapter_name, document_type, rule_ref_text, rule_reference_array, rules_type, chapter_id FROM casebook WHERE id = '6_3_10_beach';
