-- 3. and 4. Current 5.1.5, new 5.1.6 and 6.3.10
UPDATE casebook SET case_text = 'What should the referee do if a ball landed inside the line, but obviously the line had been displaced substantially during a previous defending action?', case_ruling = 'The 1st Referee should have the line corrected, and then call the ball “in” or “out”, depending on where the ball landed.', rule_ref_text = 'Rules 8.3, 8.4, Referee Guidelines and Instructions', rule_reference_array = '["rules/Rule8_3_beach", "rules/Rule8_4_beach"]' WHERE id = '5_1_5_beach';
DELETE FROM casebook_rules WHERE casebook_id = '5_1_5_beach';
INSERT INTO casebook_rules (casebook_id, rule_id) VALUES ('5_1_5_beach', 'Rule8_3_beach');
INSERT INTO casebook_rules (casebook_id, rule_id) VALUES ('5_1_5_beach', 'Rule8_4_beach');
INSERT INTO casebook (id, case_number, case_text, case_ruling, video_link, case_section, case_subsection, chapter_n, chapter_name, document_type, rule_ref_text, rule_reference_array, rules_type, chapter_id) VALUES ('5_1_6_beach', '5.1.6', 'What should the referee do if a ball was played inside the court, touching the side line but obviously the line was minimally displaced during a previous defending action?', 'In this case the 1st Referee should call the ball “in”. Small movements of the lines during a rally shall not result in the replacement of the line and a decision would be made with the line in its position at the end of the rally.
The exception to this would be if the line would have been displaced at the very last stages of the play.', NULL, 'Playing Actions', 'States Of Play', '5', 'Chapter 5', 'casebook', 'Rules 8.3, 8.4, Referee Guidelines and Instructions', '["rules/Rule8_3_beach", "rules/Rule8_4_beach"]', 'beach', 'Chapter5_beach');
DELETE FROM casebook_rules WHERE casebook_id = '5_1_6_beach';
INSERT INTO casebook_rules (casebook_id, rule_id) VALUES ('5_1_6_beach', 'Rule8_3_beach');
INSERT INTO casebook_rules (casebook_id, rule_id) VALUES ('5_1_6_beach', 'Rule8_4_beach');
INSERT INTO casebook (id, case_number, case_text, case_ruling, video_link, case_section, case_subsection, chapter_n, chapter_name, document_type, rule_ref_text, rule_reference_array, rules_type, chapter_id) VALUES ('6_3_10_beach', '6.3.10', 'If a tree branch is hanging over the service zone, and this was previously approved and officially communicated by the Technical Delegate, is the player making a fault when by throwing the ball into the air for the service, the ball hits the branch?', 'The player is not committing any fault. If the Technical Delegate approved and officially communicated these special circumstances, the 1st Referee should call a replay of the service.', NULL, 'Time Outs And Delays', 'Exceptional Game Interruptions', '6', 'Chapter 6', 'casebook', 'Rules 1.1, 8.4.2, 17.2', '["rules/Rule8_4_2_beach", "rules/Rule17_2_beach"]', 'beach', 'Chapter6_beach');
DELETE FROM casebook_rules WHERE casebook_id = '6_3_10_beach';
INSERT INTO casebook_rules (casebook_id, rule_id) VALUES ('6_3_10_beach', 'Rule8_4_2_beach');
INSERT INTO casebook_rules (casebook_id, rule_id) VALUES ('6_3_10_beach', 'Rule17_2_beach');

-- 5. Dropped case
DELETE FROM casebook_rules WHERE casebook_id = '9_20_beach';
DELETE FROM casebook WHERE id = '9_20_beach';
